import json, urllib.request

MCP = "http://127.0.0.1:40573/mcp/59f09f1d7eee2cb3089434f1fb660741"

def rpc(method, params, rid=1):
    data = json.dumps({"jsonrpc": "2.0", "id": rid, "method": method, "params": params}).encode()
    req = urllib.request.Request(MCP, data=data, headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=60) as r:
        return json.loads(r.read().decode())

def api_search(query, top_k=5):
